import { NextResponse } from "next/server";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";
export const maxDuration = 300;

type JsonRecord = Record<string, unknown>;
type Role = "system" | "user" | "assistant" | "tool";
type InputMessage = {
  role?: unknown;
  content?: unknown;
  parts?: unknown;
  name?: unknown;
  tool_call_id?: unknown;
};

const API_URL = "";
const MODEL = "minimax-m2.7";
const DEFAULT_TEMPERATURE = 0.2;
const MAX_COMPLETION_TOKENS = toPositiveInteger(
  process.env.GENERALCOMPUTE_MAX_COMPLETION_TOKENS,
  65536
);

function toPositiveInteger(value: unknown, fallback: number): number {
  const n =
    typeof value === "number"
      ? value
      : typeof value === "string" && value.trim() !== ""
        ? Number(value)
        : NaN;
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : fallback;
}

function toBoundedNumber(
  value: unknown,
  min: number,
  max: number,
  fallback: number
): number {
  const n =
    typeof value === "number"
      ? value
      : typeof value === "string" && value.trim() !== ""
        ? Number(value)
        : NaN;
  if (!Number.isFinite(n)) return fallback;
  return Math.min(max, Math.max(min, n));
}

function toText(value: unknown): string {
  if (typeof value === "string") return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return "";
}

function extractText(value: unknown): string {
  if (typeof value === "string") return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  if (Array.isArray(value)) return value.map(extractText).join("");
  if (value && typeof value === "object") {
    const obj = value as JsonRecord;
    if ((obj.type === "text" || obj.type === "input_text") && typeof obj.text === "string") {
      return obj.text;
    }
    if (typeof obj.text === "string") return obj.text;
    if (typeof obj.content === "string") return obj.content;
    if (Array.isArray(obj.content)) return obj.content.map(extractText).join("");
  }
  return "";
}

function normalizeMessage(message: InputMessage): JsonRecord | null {
  const rawRole = toText(message.role).trim().toLowerCase();
  const role: Role =
    rawRole === "system" ||
    rawRole === "assistant" ||
    rawRole === "tool"
      ? rawRole
      : "user";
  const content = [extractText(message.parts), extractText(message.content)]
    .find((value) => value.trim().length > 0)
    ?.trim() ?? "";
  if (!content) return null;
  const normalized: JsonRecord = { role, content };
  const name = toText(message.name).trim();
  if (name) normalized.name = name;
  const toolCallId = toText(message.tool_call_id).trim();
  if (role === "tool" && toolCallId) normalized.tool_call_id = toolCallId;
  return normalized;
}

function pick(body: JsonRecord, key: string): unknown {
  return Object.prototype.hasOwnProperty.call(body, key) ? body[key] : undefined;
}

function addIfDefined(target: JsonRecord, body: JsonRecord, key: string): void {
  const value = pick(body, key);
  if (value !== undefined) target[key] = value;
}

function buildMessages(body: JsonRecord): JsonRecord[] {
  const system = toText(body.system).trim();
  const incoming = Array.isArray(body.messages) ? body.messages : [];
  const normalized = incoming
    .map((message) => normalizeMessage((message ?? {}) as InputMessage))
    .filter((message): message is JsonRecord => message !== null);
  return system ? [{ role: "system", content: system }, ...normalized] : normalized;
}

function buildStreamHeaders(upstream: Response): Headers {
  const headers = new Headers();
  headers.set("Content-Type", "text/event-stream; charset=utf-8");
  headers.set("Cache-Control", "no-cache, no-transform");
  headers.set("Connection", "keep-alive");
  headers.set("X-Accel-Buffering", "no");
  const passthrough = [
    "x-request-id",
    "x-ratelimit-limit-requests",
    "x-ratelimit-remaining-requests",
    "x-ratelimit-reset-requests",
  ];
  for (const key of passthrough) {
    const value = upstream.headers.get(key);
    if (value) headers.set(key, value);
  }
  return headers;
}

export async function POST(req: Request) {
  const apiKey = process.env.GENERALCOMPUTE_API_KEY?.trim();
  if (!apiKey) {
    return NextResponse.json(
      { error: "Missing GENERALCOMPUTE_API_KEY" },
      { status: 500 }
    );
  }

  let parsed: unknown;

  try {
    parsed = await req.json();
  } catch {
    return NextResponse.json(
      { error: "Invalid JSON body" },
      { status: 400 }
    );
  }

  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    return NextResponse.json(
      { error: "Request body must be an object" },
      { status: 400 }
    );
  }

  const body = parsed as JsonRecord;
  const messages = buildMessages(body);

  if (messages.length === 0) {
    return NextResponse.json(
      { error: "At least one message is required" },
      { status: 400 }
    );
  }

  const payload: JsonRecord = {
    model: MODEL,
    messages,
    stream: true,
    temperature: toBoundedNumber(body.temperature, 0, 2, DEFAULT_TEMPERATURE),
    max_completion_tokens: MAX_COMPLETION_TOKENS,
  };

  for (const key of [
    "top_p",
    "presence_penalty",
    "frequency_penalty",
    "stop",
    "tools",
    "tool_choice",
    "parallel_tool_calls",
    "response_format",
    "seed",
    "user",
  ]) {
    addIfDefined(payload, body, key);
  }

  let upstream: Response;

  try {
    upstream = await fetch(API_URL, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
        Accept: "text/event-stream",
      },
      body: JSON.stringify(payload),
      signal: req.signal,
      cache: "no-store",
    });
  } catch (error) {
    const message =
      error instanceof Error && error.message
        ? error.message
        : "Upstream request failed";
    return NextResponse.json({ error: message }, { status: 502 });
  }

  if (!upstream.ok) {
    const text = await upstream.text().catch(() => "");
    const contentType = upstream.headers.get("content-type") ?? "";
    if (contentType.includes("application/json") && text) {
      return new Response(text, {
        status: upstream.status,
        headers: {
          "Content-Type": "application/json; charset=utf-8",
          "Cache-Control": "no-store",
        },
      });
    }
    return NextResponse.json(
      {
        error: text || "Upstream request failed",
        status: upstream.status,
      },
      { status: upstream.status }
    );
  }

  if (!upstream.body) {
    return NextResponse.json(
      { error: "Upstream stream unavailable" },
      { status: 502 }
    );
  }

  return new Response(upstream.body, {
    status: upstream.status,
    headers: buildStreamHeaders(upstream),
  });
}
