```python
import os
from openai import OpenAI, APIConnectionError, APIStatusError, APITimeoutError, OpenAIError, RateLimitError
import argparse
import json
import logging
import sys
import time
from dataclasses import dataclass
from typing import Any, Iterable, Optional

import httpx


@dataclass(frozen=True)
class Config:
    api_key: str
    base_url: str
    model: str
    system_prompt: str
    prompt: str
    temperature: float
    top_p: float
    presence_penalty: float
    frequency_penalty: float
    max_completion_tokens: int
    connect_timeout: float
    read_timeout: float
    write_timeout: float
    pool_timeout: float
    max_retries: int
    retry_base_delay: float
    retry_max_delay: float
    seed: Optional[int]


def positive_int(value: str) -> int:
    try:
        parsed = int(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(f"invalid integer: {value}") from exc
    if parsed <= 0:
        raise argparse.ArgumentTypeError(f"value must be greater than 0: {value}")
    return parsed


def non_negative_int(value: str) -> int:
    try:
        parsed = int(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(f"invalid integer: {value}") from exc
    if parsed < 0:
        raise argparse.ArgumentTypeError(f"value must be greater than or equal to 0: {value}")
    return parsed


def positive_float(value: str) -> float:
    try:
        parsed = float(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(f"invalid float: {value}") from exc
    if parsed <= 0:
        raise argparse.ArgumentTypeError(f"value must be greater than 0: {value}")
    return parsed


def bounded_float(minimum: float, maximum: float):
    def parser(value: str) -> float:
        try:
            parsed = float(value)
        except ValueError as exc:
            raise argparse.ArgumentTypeError(f"invalid float: {value}") from exc
        if parsed < minimum or parsed > maximum:
            raise argparse.ArgumentTypeError(f"value must be between {minimum} and {maximum}: {value}")
        return parsed
    return parser


def optional_int(value: str) -> Optional[int]:
    text = value.strip().lower()
    if text in {"", "none", "null"}:
        return None
    try:
        return int(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(f"invalid integer: {value}") from exc


def env(name: str, default: Optional[str] = None) -> Optional[str]:
    value = os.getenv(name)
    if value is None:
        return default
    return value.strip()


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="minimax_m27_stream")
    parser.add_argument("prompt", nargs="?", default=None)
    parser.add_argument("--system-prompt", default=env("GENERALCOMPUTE_SYSTEM_PROMPT", "You are a helpful assistant."))
    parser.add_argument("--model", default=env("GENERALCOMPUTE_MODEL", "minimax-m2.7"))
    parser.add_argument("--base-url", default=env("GENERALCOMPUTE_BASE_URL", ""))
    parser.add_argument("--temperature", type=bounded_float(0.0, 2.0), default=float(env("GENERALCOMPUTE_TEMPERATURE", "0.2")))
    parser.add_argument("--top-p", type=bounded_float(0.0, 1.0), default=float(env("GENERALCOMPUTE_TOP_P", "1.0")))
    parser.add_argument("--presence-penalty", type=bounded_float(-2.0, 2.0), default=float(env("GENERALCOMPUTE_PRESENCE_PENALTY", "0.0")))
    parser.add_argument("--frequency-penalty", type=bounded_float(-2.0, 2.0), default=float(env("GENERALCOMPUTE_FREQUENCY_PENALTY", "0.0")))
    parser.add_argument("--max-completion-tokens", type=positive_int, default=int(env("GENERALCOMPUTE_MAX_COMPLETION_TOKENS", "128000")))
    parser.add_argument("--connect-timeout", type=positive_float, default=float(env("GENERALCOMPUTE_CONNECT_TIMEOUT", "10")))
    parser.add_argument("--read-timeout", type=positive_float, default=float(env("GENERALCOMPUTE_READ_TIMEOUT", "1800")))
    parser.add_argument("--write-timeout", type=positive_float, default=float(env("GENERALCOMPUTE_WRITE_TIMEOUT", "120")))
    parser.add_argument("--pool-timeout", type=positive_float, default=float(env("GENERALCOMPUTE_POOL_TIMEOUT", "30")))
    parser.add_argument("--max-retries", type=non_negative_int, default=int(env("GENERALCOMPUTE_MAX_RETRIES", "4")))
    parser.add_argument("--retry-base-delay", type=positive_float, default=float(env("GENERALCOMPUTE_RETRY_BASE_DELAY", "1.5")))
    parser.add_argument("--retry-max-delay", type=positive_float, default=float(env("GENERALCOMPUTE_RETRY_MAX_DELAY", "20")))
    parser.add_argument("--seed", type=optional_int, default=optional_int(env("GENERALCOMPUTE_SEED", "none") or "none"))
    return parser


def configure_logging() -> logging.Logger:
    logger = logging.getLogger("minimax_m27_stream")
    logger.setLevel(logging.INFO)
    logger.handlers.clear()
    handler = logging.StreamHandler(sys.stderr)
    handler.setLevel(logging.INFO)
    handler.setFormatter(logging.Formatter("%(asctime)s %(levelname)s %(message)s", "%Y-%m-%dT%H:%M:%S%z"))
    logger.addHandler(handler)
    logger.propagate = False
    return logger


def resolve_prompt(cli_prompt: Optional[str]) -> str:
    if cli_prompt is not None and cli_prompt.strip():
        return cli_prompt.strip()
    stdin_text = sys.stdin.read()
    if stdin_text and stdin_text.strip():
        return stdin_text.strip()
    raise ValueError("prompt is required via argument or stdin")


def load_config() -> Config:
    parser = build_parser()
    args = parser.parse_args()
    api_key = env("GENERALCOMPUTE_API_KEY", "") or ""
    if not api_key:
        raise ValueError("GENERALCOMPUTE_API_KEY is missing")
    prompt = resolve_prompt(args.prompt)
    base_url = str(args.base_url).rstrip("/")
    if not base_url:
        raise ValueError("base URL is missing")
    return Config(
        api_key=api_key,
        base_url=base_url,
        model=str(args.model).strip(),
        system_prompt=str(args.system_prompt).strip(),
        prompt=prompt,
        temperature=float(args.temperature),
        top_p=float(args.top_p),
        presence_penalty=float(args.presence_penalty),
        frequency_penalty=float(args.frequency_penalty),
        max_completion_tokens=int(args.max_completion_tokens),
        connect_timeout=float(args.connect_timeout),
        read_timeout=float(args.read_timeout),
        write_timeout=float(args.write_timeout),
        pool_timeout=float(args.pool_timeout),
        max_retries=int(args.max_retries),
        retry_base_delay=float(args.retry_base_delay),
        retry_max_delay=float(args.retry_max_delay),
        seed=args.seed,
    )


def build_client(config: Config) -> OpenAI:
    timeout = httpx.Timeout(
        connect=config.connect_timeout,
        read=config.read_timeout,
        write=config.write_timeout,
        pool=config.pool_timeout,
    )
    return OpenAI(
        api_key=config.api_key,
        base_url=f"{config.base_url}/v1",
        timeout=timeout,
        max_retries=0,
    )


def is_retryable_error(exc: Exception) -> bool:
    if isinstance(exc, (APIConnectionError, APITimeoutError, RateLimitError)):
        return True
    if isinstance(exc, APIStatusError):
        return exc.status_code in {408, 409, 429, 500, 502, 503, 504}
    return False


def retry_delay(attempt: int, base_delay: float, max_delay: float) -> float:
    return min(max_delay, base_delay * (2 ** (attempt - 1)))


def extract_text_chunks(stream: Iterable[Any]) -> Iterable[str]:
    for chunk in stream:
        choices = getattr(chunk, "choices", None)
        if not choices:
            continue
        choice = choices[0]
        delta = getattr(choice, "delta", None)
        if delta is None:
            continue
        content = getattr(delta, "content", None)
        if isinstance(content, str) and content:
            yield content


def request_stream(client: OpenAI, config: Config) -> Iterable[Any]:
    payload: dict[str, Any] = {
        "model": config.model,
        "messages": [
            {"role": "system", "content": config.system_prompt},
            {"role": "user", "content": config.prompt},
        ],
        "stream": True,
        "temperature": config.temperature,
        "top_p": config.top_p,
        "presence_penalty": config.presence_penalty,
        "frequency_penalty": config.frequency_penalty,
        "max_completion_tokens": config.max_completion_tokens,
    }
    if config.seed is not None:
        payload["seed"] = config.seed
    return client.chat.completions.create(**payload)


def run_stream(client: OpenAI, config: Config, logger: logging.Logger) -> str:
    attempt = 0
    while True:
        attempt += 1
        stream = None
        try:
            stream = request_stream(client, config)
            parts: list[str] = []
            emitted_any = False
            for text in extract_text_chunks(stream):
                emitted_any = True
                parts.append(text)
                sys.stdout.write(text)
                sys.stdout.flush()
            if not emitted_any:
                raise RuntimeError("model returned no text content")
            if not parts[-1].endswith("\n"):
                sys.stdout.write("\n")
                sys.stdout.flush()
            return "".join(parts)
        except Exception as exc:
            if stream is not None:
                close_method = getattr(stream, "close", None)
                if callable(close_method):
                    try:
                        close_method()
                    except Exception:
                        pass
            if isinstance(exc, RuntimeError):
                raise
            if not is_retryable_error(exc) or attempt > config.max_retries + 1:
                raise
            delay = retry_delay(attempt - 1, config.retry_base_delay, config.retry_max_delay)
            logger.warning(json.dumps({"event": "retry", "attempt": attempt - 1, "delay_seconds": delay, "error_type": exc.__class__.__name__, "error": str(exc)}, ensure_ascii=False))
            time.sleep(delay)
        finally:
            if stream is not None:
                close_method = getattr(stream, "close", None)
                if callable(close_method):
                    try:
                        close_method()
                    except Exception:
                        pass


def main() -> int:
    logger = configure_logging()
    try:
        config = load_config()
        client = build_client(config)
        logger.info(json.dumps({"event": "request_start", "model": config.model, "max_completion_tokens": config.max_completion_tokens, "temperature": config.temperature, "top_p": config.top_p, "presence_penalty": config.presence_penalty, "frequency_penalty": config.frequency_penalty, "seed": config.seed}, ensure_ascii=False))
        text = run_stream(client, config, logger)
        logger.info(json.dumps({"event": "request_complete", "output_characters": len(text)}, ensure_ascii=False))
        return 0
    except (APIConnectionError, APITimeoutError, RateLimitError, APIStatusError, OpenAIError, httpx.HTTPError, ValueError, RuntimeError) as exc:
        logging.getLogger("minimax_m27_stream").error(json.dumps({"event": "request_failed", "error_type": exc.__class__.__name__, "error": str(exc)}, ensure_ascii=False))
        return 1
    except Exception as exc:
        logging.getLogger("minimax_m27_stream").error(json.dumps({"event": "unexpected_failure", "error_type": exc.__class__.__name__, "error": str(exc)}, ensure_ascii=False))
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
